<?php
session_start();require __DIR__.'/../vendor/autoload.php';require __DIR__.'/../config/db.php';require __DIR__.'/../includes/auth_check.php';
use PhpOffice\PhpSpreadsheet\IOFactory;use PhpOffice\PhpSpreadsheet\Spreadsheet;use PhpOffice\PhpSpreadsheet\Writer\Xlsx;
if(!in_array($_SESSION['role'],['super_admin','inventory_admin','manager'],true))die('Access denied.');$uid=(int)$_SESSION['user_id'];$role=$_SESSION['role'];$q=$conn->prepare('SELECT branch FROM users WHERE id=?');$q->execute([$uid]);$userBranch=(string)($q->fetchColumn()?:'KIMATHI');$cats=$conn->query('SELECT id,category_name FROM categories')->fetchAll(PDO::FETCH_ASSOC);$map=[];foreach($cats as$c)$map[strtolower(trim($c['category_name']))]=$c;$success='';$error='';$duplicates=[];$invalid=[];$monitors=[];
function ramv($v){return preg_match('/(\d{1,3})/',(string)$v,$m)?(int)$m[1]:0;}function storv($v){$r=strtoupper(trim((string)$v));$t=preg_match('/\b(SSD|NVME)\b/',$r)?'SSD':(preg_match('/\bHDD\b/',$r)?'HDD':'SSD');$c=0;if(preg_match('/(\d+(?:\.\d+)?)\s*TB/',$r,$m))$c=(int)round((float)$m[1]*1000);elseif(preg_match('/(\d+(?:\.\d+)?)\s*GB/',$r,$m))$c=(int)$m[1];return[$t,$c];}function touchv($v){$x=strtolower(trim((string)$v));if(in_array($x,['yes','touch','touchscreen','touch screen'],true))return'Touch';if(in_array($x,['no','non-touch','non touch'],true))return'Non-touch';return'N/A';}
if(isset($_GET['template'])){$b=new Spreadsheet();$s=$b->getActiveSheet();$s->fromArray([['serial_number','category','specs'],['5CG123','Laptop','HP EliteBook 840 G8 | Core i5 11th | 16GB | 512GB SSD | Intel Iris | Non-touch | Ex-Uk | AC16 | KIMATHI']]);while(ob_get_level())ob_end_clean();header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="normal_inventory_upload_template.xlsx"');(new Xlsx($b))->save('php://output');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_FILES['excel_file'])){try{$b=IOFactory::load($_FILES['excel_file']['tmp_name']);$rows=$b->getActiveSheet()->toArray(null,true,true,false);$head=array_map(fn($v)=>strtolower(trim((string)$v)),array_shift($rows));$idx=array_flip($head);foreach(['serial_number','category','specs']as$r)if(!isset($idx[$r]))throw new Exception("Missing column: $r");$check=$conn->prepare('SELECT 1 FROM devices WHERE serial_number=? LIMIT 1');$ins=$conn->prepare("INSERT INTO devices(serial_number,category_id,model_name,processor,graphics,ram,storage_type,storage_capacity,touch,status,device_condition,added_by,branch,cargo_number,place,inventory_owner) VALUES(?,?,?,?,?,?,?,?,?,'In Stock',?,?,?,?,?,NULL)");$count=0;foreach($rows as$i=>$row){if(!array_filter($row,fn($v)=>trim((string)$v)!==''))continue;$serial=trim((string)($row[$idx['serial_number']]??''));$catName=trim((string)($row[$idx['category']]??''));if(stripos($catName,'monitor')!==false){$monitors[]=$serial?:'Row '.($i+2);continue;}$cat=$map[strtolower($catName)]??null;$parts=array_map('trim',preg_split('/\s*[|,]\s*/',(string)($row[$idx['specs']]??''))?:[]);$model=$parts[0]??'';$cpu=$parts[1]??'';$ram=ramv($parts[2]??'');[$stype,$scap]=storv($parts[3]??'');$graphics=($parts[4]??'')?:'None';$touch=touchv($parts[5]??'');$cond=strtolower($parts[6]??'');$condition=in_array($cond,['refurbished','refurb','ref'],true)?'Refurbished':($cond==='new'?'New':'Ex-Uk');$cargo=trim($parts[7]??'');if($cargo===''||$cargo==='-')$cargo='NO CARGO';$branch=strtoupper(trim($parts[8]??''));if(!in_array($branch,['KIMATHI','MOI','WAREHOUSE'],true))$branch=$userBranch;$place=$branch==='WAREHOUSE'?'warehouse':(strtolower($catName)==='laptop'?'store':'display');$errs=[];if($serial==='')$errs[]='Serial required';if(!$cat)$errs[]='Category not found';if($model==='')$errs[]='Model required';if($cpu==='')$errs[]='Processor required';if($ram<1)$errs[]='RAM invalid';if($scap<1)$errs[]='Storage invalid';if($errs){$invalid[]='Row '.($i+2).': '.implode('; ',$errs);continue;}$check->execute([$serial]);if($check->fetchColumn()){$duplicates[]=$serial;continue;}$ins->execute([$serial,$cat['id'],$model,$cpu,$graphics,$ram,$stype,$scap,$touch,$condition,$uid,$branch,$cargo,$place]);$count++;}$success="$count device(s) uploaded successfully.";}catch(Throwable$e){$error=$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bulk Upload Devices</title><style>body{font-family:Inter,system-ui;background:#f3f4f6;margin:0}.main{margin-left:260px;padding:2rem}.box{background:white;padding:1.4rem;border-radius:14px;margin-bottom:1rem}.btn{background:#1a4b2a;color:#fff;border:0;padding:.75rem 1rem;border-radius:8px;text-decoration:none;display:inline-block}.alert{padding:1rem;margin-bottom:1rem}.help{color:#6b7280;line-height:1.6}input{padding:.7rem;width:100%}@media(max-width:1200px){.main{margin-left:0;padding:5rem 1rem}}</style></head><body><?php include __DIR__.'/../includes/sidebar.php';?><main class="main"><div class="box"><h1>Normal Devices Bulk Upload</h1><p class="help">This page now uploads <strong>normal devices only</strong> into the devices table. Iman Inventory and Iman's Hustle have their own Bulk Upload pages inside their folders.</p><a class="btn" href="?template=1">Download .xlsx Template</a></div><?php if($success):?><div class="alert"><?=htmlspecialchars($success)?></div><?php endif;?><?php if($error):?><div class="alert"><?=htmlspecialchars($error)?></div><?php endif;?><?php if($duplicates):?><div class="alert">Duplicates: <?=htmlspecialchars(implode(', ',$duplicates))?></div><?php endif;?><?php if($monitors):?><div class="alert">Monitor rows skipped: <?=htmlspecialchars(implode(', ',$monitors))?></div><?php endif;?><?php if($invalid):?><div class="alert"><ul><?php foreach($invalid as$e):?><li><?=htmlspecialchars($e)?></li><?php endforeach;?></ul></div><?php endif;?><div class="box"><form method="post" enctype="multipart/form-data"><input type="file" name="excel_file" accept=".xlsx,.xls,.csv" required><button class="btn" style="margin-top:1rem">Upload and Process</button></form></div></main><?php require_once __DIR__.'/../includes/footer.php';?></body></html>
